tabulate⁻ : ∀ {n} {f : Fin n → A} → Any P (tabulate f) → ∃ λ i → P (f i)
-- Base case: n is zero, so tabulate f is [] and Any P [] is empty.
tabulate⁻ {zero} p = {!!}
-- Inductive case, head: the match is at the first element, so the index is zero.
tabulate⁻ {suc n} (here px) = {!!}
-- Inductive case, tail: recurse on the tail with the induction hypothesis.
tabulate⁻ {suc n} (there pxs) = {!!}

tabulate⁻ : ∀ {n} {f : Fin n → A} → Any P (tabulate f) → ∃ λ i → P (f i)
-- Base case: n is zero, so tabulate f is [] and Any P [] is empty.
tabulate⁻ {n = zero} p = {!!}
-- Inductive case, head: the match is at the first element, so the index is zero.
tabulate⁻ {n = suc n} (here px) = {!!}
-- Inductive case, tail: recurse on the tail with the induction hypothesis.
tabulate⁻ {n = suc n} (there pxs) = {!!}

